service.method:

SELECT
	USER_ID
	, COMPANY_CODE
FROM
	SUSMT
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND USER_ID = ${value}


		SELECT
			CREATOR AS USER_ID
			, COMPANY_CODE
            , CONT_TYPE
		FROM
			SCTGL
		WHERE
			HOUSE_CODE = ${session.HOUSE_CODE}
			AND CONT_NO = ${CONT_NO}
			AND CONT_GL_SEQ = ${CONT_GL_SEQ}


SELECT
	SIGNER_ID AS USER_ID
	,SIGNER_COMPANY_CODE AS COMPANY_CODE
FROM
	SSIGN
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND CONT_NO = ${CONT_NO}
	AND CONT_GL_SEQ = ${CONT_GL_SEQ}


SELECT
	REVIEWER_ID AS USER_ID
	, REVIEWER_COMPANY_CODE AS COMPANY_CODE
FROM
	SCTRV
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND CONT_NO = ${CONT_NO}
	AND CONT_GL_SEQ = ${CONT_GL_SEQ}


SELECT
	*
FROM
	SDCAM
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND CODE = ${CONT_NO}
	AND SEQ = ${CONT_GL_SEQ}
